ntWeight":400},"datasources":[{"name":"function","type":"function","dataKeys":[{"name":"f(x)","type":"function","_hash":0.15479322438769105,"color":"#2196f3","label":"Temperature","funcBody":"const baseTemp = 20;\nconst dailySwing = 10;\nconst hourlyVariation = Math.sin((time % 24) * Math.PI / 12) * dailySwing;\nconst randomness = (Math.random() - 0.5) * 2;\nconst smoothingFactor = 0.8;\nreturn (prevValue * smoothingFactor) + ((baseTemp + hourlyVariation + randomness) * (1 -  smoothingFactor));","settings":{}}],"alarmFilterConfig":{"statusList":["ACTIVE"]}}],"widgetStyle":{},"titleTooltip":"","showTitleIcon":false,"backgroundColor":"#fff","enableFullscreen":true}', '{}', '["web","markup"]', '{"sourceFqn":"cards.markdown_card","seedOrigin":"thingsboard-source","sourceFile":"/Users/liulihai/Documents/ByteCode/code/liulihai/nexiot/thingsboard/application/src/main/data/json/system/widget_types/markdown_html_card.json","description":"适合做说明区、状态提示、快捷操作和组合内容。","fallbackSizeX":24,"fallbackSizeY":3.5}', 'nexiot', 1775957701531, 1775957701531, NULL);
INSERT INTO "unix_tenant_202605"."iot_viz_widget_type" ("id", "bundle_id", "widget_key", "full_fqn", "widget_name", "widget_type", "scope_type", "deprecated", "status", "image", "descriptor_json", "default_config_json", "schema_json", "tags_json", "metadata_json", "creator_id", "create_time", "update_time", "tenant_id") VALUES (2043140802615689216, 2043140802204647424, 'attributes_card', 'system.cards.attributes_card', '属性卡片', 'latest', 'SYSTEM', 0, 0, 'tb-image;/api/images/system/attributes_card_system_widget_image.png', '{"type":"latest","sizeX":7.5,"sizeY":3,"resources":[],"templateCss":"#container {\n    overflow: auto;\n}\n\n.tbDatasource-container {\n    margin: 5px;\n    padding: 8px;\n}\n\n.tbDatasource-title {\n    font-size: 1.200rem;\n    font-weight: 500;\n    padding-bottom: 10px;\n}\n\n.tbDatasource-table {\n    width: 100%;\n    box-shadow: 0 0 10px #ccc;\n    border-collapse: collapse;\n    white-space: nowrap;\n    font-size: 1.000rem;\n    color: #757575;\n}\n\n.tbDatasource-table td {\n    position: relative;\n    border-top: 1px solid rgba(0, 0, 0, 0.12);\n    border-bottom: 1px solid rgba(0, 0, 0, 0.12);\n    padding: 0px 18px;\n    box-sizing: border-box;\n}","templateHtml":"","settingsSchema":{},"controllerScript":"self.onInit = function() {\n\n    self.ctx.datasourceTitleCells = [];\n    self.ctx.valueCells = [];\n    self.ctx.labelCells = [];\n\n    for (var i = 0; i < self.ctx.datasources\n        .length; i++) {\n        var tbDatasource = self.ctx.datasources[i];\n\n        var datasourceId = ''tbDatasource'' + i;\n        self.ctx.$container.append(\n            \"<div id=''\" + datasourceId +\n            \"'' class=''tbDatasource-container''></div>\"\n        );\n\n        var datasourceContainer = $(''#'' + datasourceId,\n            self.ctx.$container);\n\n        datasourceContainer.append(\n            \"<div class=''tbDatasource-title''>\" +\n            tbDatasource.name + \"</div>\"\n        );\n\n        var datasourceTitleCell = $(\n            ''.tbDatasource-title'',\n            datasourceContainer);\n        self.ctx.datasourceTitleCells.push(\n            datasourceTitleCell);\n\n        var tableId = ''table'' + i;\n        datasourceContainer.append(\n            \"<table id=''\" + tableId +\n            \"'' class=''tbDatasource-table''><col width=''30%''><col width=''70%''></table>\"\n        );\n        var table = $(''#'' + tableId, self.ctx\n            .$container);\n\n        for (var a = 0; a < tbDatasource.dataKeys\n            .length; a++) {\n            var dataKey = tbDatasource.dataKeys[a];\n            var labelCellId = ''labelCell'' + a;\n            var cellId = ''cell'' + a;\n            table.append(\"<tr><td id=''\" + labelCellId +\n                \"''>\" + dataKey.label +\n                \"</td><td id=''\" + cellId +\n                \"''></td></tr>\");\n            var labelCell = $(''#'' + labelCellId, table);\n            self.ctx.labelCells.push(labelCell);\n            var valueCell = $(''#'' + cellId, table);\n            self.ctx.valueCells.push(valueCell);\n        }\n    }\n\n    self.onResize();\n}\n\nself.onDataUpdated = function() {\n    for (var i = 0; i < self.ctx.valueCells\n        .length; i++) {\n        var cellData = self.ctx.data[i];\n        if (cellData && cellData.data && cellData.data\n            .length > 0) {\n            var tvPair = cellData.data[cellData.data\n                .length -\n                1];\n            var value = tvPair[1];\n            var textValue;\n            //toDo -> + IsNumber\n\n            if (isNumber(value)) {\n                var decimals = self.ctx.decimals;\n                var units = self.ctx.units;\n                if (cellData.dataKey.decimals ||\n                    cellData.dataKey.decimals === 0) {\n                    decimals = cellData.dataKey\n                        .decimals;\n                }\n                if (cellData.dataKey.units) {\n                    units = cellData.dataKey.units;\n                }\n                txtValue = self.ctx.utils.formatValue(\n                    value, decimals, units, true);\n            } else {\n                txtValue = self.ctx.utilsService\n                    .customTranslation(value);\n            }\n            self.ctx.valueCells[i].html(txtValue);\n        }\n    }\n\n    function isNumber(n) {\n        return !isNaN(parseFloat(n)) && isFinite(n);\n    }\n}\n\nself.onResize = function() {\n    var datasourceTitleFontSize = self.ctx.height / 8;\n    if (self.ctx.width / self.ctx.height <= 1.5) {\n        datasourceTitleFontSize = self.ctx.width / 12;\n    }\n    datasourceTitleFontSize = Math.min(\n        datasourceTitleFontSize, 20);\n    for (var i = 0; i < self.ctx.datasourceTitleCells\n        .length; i++) {\n        self.ctx.datasourceTitleCells[i].css(\n            ''font-size'', datasourceTitleFontSize +\n            ''px'');\n    }\n    var valueFontSize = self.ctx.height / 9;\n    var labelFontSize = self.ctx.height / 9;\n    if (self.ctx.width / self.ctx.height <= 1.5) {\n        valueFontSize = self.ctx.width / 15;\n        labelFontSize = self.ctx.width / 15;\n    }\n    valueFontSize = Math.min(valueFontSize, 18);\n    labelFontSize = Math.min(labelFontSize, 18);\n\n    for (i = 0; i < self.ctx.valueCells; i++) {\n        self.ctx.valueCells[i].css(''font-size'',\n            valueFontSize + ''px'');\n        self.ctx.valueCells[i].css(''height'',\n            valueFontSize * 2.5 + ''px'');\n        self.ctx.valueCells[i].css(''padding'', ''0px '' +\n            valueFontSize + ''px'');\n        self.ctx.labelCells[i].css(''font-size'',\n            labelFontSize + ''px'');\n        self.ctx.labelCells[i].css(''height'',\n            labelFontSize * 2.5 + ''px'');\n        self.ctx.labelCells[i].css(''padding'', ''0px '' +\n            labelFontSize + ''px'');\n    }\n}\n\nself.onDestroy = function() {}","dataKeySettingsSchema":{}}', '{"color":"rgba(0, 0, 0, 0.87)","title":"属性卡片","padding":"8px","settings":{},"showTitle":true,"datasources":[{"name":"function","type":"function","dataKeys":[{"name":"f(x)","type":"function","_hash":0.15479322438769105,"color":"#2196f3","label":"Random","funcBody":"var value = prevValue + Math.random() * 100 - 50;\nvar multiplier = Math.pow(10, 2 || 0);\nvar value = Math.round(value * multiplier) / multiplier;\nif (value < -1000) {\n\tvalue = -1000;\n} else if (value > 1000) {\n\tvalue = 1000;\n}\nreturn value;","settings":{}}]}],"backgroundColor":"#fff"}', '{}', '[]', '{"sourceFqn":"cards.attributes_card","seedOrigin":"thingsboard-source","sourceFile":"/Users/liulihai/Documents/ByteCode/code/liulihai/nexiot/thingsboard/application/src/main/data/json/system/widget_types/attributes_card.json","description":"适合展示单设备属性、标签和静态信息面板。","fallbackSizeX":4.5,"fallbackSizeY":3.5}', 'nexiot', 1775957701531, 1775957701531, NULL);
